            // Also check v1-1, v1+1, v2-1, v2+1 just in case
            for (let delta = -2; delta <= 2; delta++) {
                const c1 = v1 + delta;
                const c2 = v2 + delta;
                if (c1 >= rangeL && c1 <= rangeR) candidates.add(c1);
                if (c2 >= rangeL && c2 <= rangeR) candidates.add(c2);
            }

            for (const c of candidates) {
                check(c);
            }
        }

        return maxW;
    }

    return maxWeightInRange(l, r);
}

// Read input
const rl = readline.createInterface({
    input: process.stdin,
    terminal: false
});

let lines = [];
